#!/usr/bin/env bash
# Rebuilds supabase/install.sql: every migration in order, one paste for the Supabase SQL editor.
set -euo pipefail
cd "$(dirname "$0")/.."
{
cat <<'SQL'
-- ============================================================
-- OpenPlate: full database install in one script
--
-- Paste into Supabase → SQL Editor → New query → Run.
-- It's every file in supabase/migrations, in order, and safe to re-run.
-- Generated by scripts/build-install-sql.sh; don't edit by hand.
--
-- After it finishes, run the two lines at the very bottom with your own
-- time zone and email (they're commented out).
-- ============================================================

SQL
  for f in supabase/migrations/*.sql; do printf '\n-- >>> %s\n' "$(basename "$f")"; cat "$f"; done
cat <<'SQL'

-- ============================================================
-- Your settings: uncomment, edit and run these two lines.
-- ============================================================
-- update public.meals_settings set timezone = 'America/New_York' where id = 1;
-- insert into public.meals_allowlist (email) values (lower('you@example.com')) on conflict (email) do nothing;
SQL
} > supabase/install.sql
echo "Wrote supabase/install.sql"
